import React from "react";
import AdForm from "./components/AddForm";

export default function App(): React.ReactElement {
  return (
    <div
      style={{
        background: "#F3F4F6",
        minHeight: "100vh", // Ensure the container takes full height
        width: "100%", // Full width of the page
        display: "flex", // Flexbox to help stretch content
        flexDirection: "column", // Ensures children stack vertically
      }}
    >
      <img
        src="public/logoAutos.jpeg" // Change this to the actual image path
        alt="Header Image"
        style={{
          width: "100%", // Image takes full width of the page
          height: "auto", // Keeps the image's aspect ratio
          maxHeight: "5rem", // Max height for the image
        }}
      />
      <AdForm />
    </div>
  );
}
